38	public class RocksDBTimeOrderedWindowStore
39	    extends WrappedStateStore<RocksDBTimeOrderedWindowSegmentedBytesStore, Object, Object>
40	    implements WindowStore<Bytes, byte[]>, TimestampedBytesStore {
41	
42	    private final boolean retainDuplicates;
43	    private final long windowSize;
44	
45	    private int seqnum = 0;
46	    private StateStoreContext stateStoreContext;
47	
48	    RocksDBTimeOrderedWindowStore(
49	        final RocksDBTimeOrderedWindowSegmentedBytesStore store,
50	        final boolean retainDuplicates,
51	        final long windowSize
52	    ) {
53	        super(store);
54	        Objects.requireNonNull(store, "store is null");
55	        this.retainDuplicates = retainDuplicates;
56	        this.windowSize = windowSize;
57	    }
58	
59	    @Override
60	    public void init(final StateStoreContext stateStoreContext, final StateStore root) {
61	        wrapped().init(stateStoreContext, root);
62	        this.stateStoreContext = stateStoreContext;
63	    }
64	
65	    @Override
66	    public void commit(final Map<TopicPartition, Long> changelogOffsets) {
67	        wrapped().commit(changelogOffsets);
68	    }
69	
70	    @Override
71	    public void close() {
72	        wrapped().close();
73	    }
74	
75	    @Override
76	    public boolean persistent() {
77	        return wrapped().persistent();
78	    }
79	
80	    @Override
81	    public boolean isOpen() {
82	        return wrapped().isOpen();
83	    }
84	
85	    @Override
86	    public void put(final Bytes key, final byte[] value, final long windowStartTimestamp) {
87	        // Skip if value is null and duplicates are allowed since this delete is a no-op
88	        if (!(value == null && retainDuplicates)) {
89	            maybeUpdateSeqnumForDups();
90	            wrapped().put(key, windowStartTimestamp, seqnum, value);
91	        }
92	    }
93	
94	    @Override
95	    public byte[] fetch(final Bytes key, final long timestamp) {
96	        return wrapped().fetch(key, timestamp, seqnum);
97	    }
98	
99	    @Override
100	    public WindowStoreIterator<byte[]> fetch(final Bytes key, final long timeFrom, final long timeTo) {
101	        final KeyValueIterator<Bytes, byte[]> bytesIterator = wrapped().fetch(key, timeFrom, timeTo);
102	        return new WindowStoreIteratorWrapper(bytesIterator,
103	            windowSize,
104	            TimeFirstWindowKeySchema::extractStoreTimestamp,
105	            TimeFirstWindowKeySchema::fromStoreBytesKey).valuesIterator();
106	    }
107	
108	    @Override
