48	    public TimestampedWindowStoreBuilder(final WindowBytesStoreSupplier storeSupplier,
49	                                         final Serde<K> keySerde,
50	                                         final Serde<V> valueSerde,
51	                                         final Time time) {
52	        super(storeSupplier.name(), keySerde, valueSerde == null ? null : new ValueAndTimestampSerde<>(valueSerde), time);
53	        Objects.requireNonNull(storeSupplier, "storeSupplier can't be null");
54	        Objects.requireNonNull(storeSupplier.metricsScope(), "storeSupplier's metricsScope can't be null");
55	        this.storeSupplier = storeSupplier;
56	    }
