58	    @Override
59	    public TimestampedWindowStore<K, V> build() {
60	        WindowStore<Bytes, byte[]> store = storeSupplier.get();
61	        if (!(store instanceof TimestampedBytesStore)) {
62	            if (store.persistent()) {
63	                store = new WindowToTimestampedWindowByteStoreAdapter(store);
64	            } else {
65	                store = new InMemoryTimestampedWindowStoreMarker(store);
66	            }
67	        }
68	        if (storeSupplier.retainDuplicates() && enableCaching) {
69	            LOG.warn("Disabling caching for {} since store was configured to retain duplicates", storeSupplier.name());
70	            enableCaching = false;
71	        }
72	
73	        return new MeteredTimestampedWindowStore<>(
74	            maybeWrapCaching(maybeWrapLogging(store)),
75	            storeSupplier.windowSize(),
76	            storeSupplier.metricsScope(),
77	            time,
78	            keySerde,
79	            valueSerde);
80	    }
