82	    private WindowStore<Bytes, byte[]> maybeWrapCaching(final WindowStore<Bytes, byte[]> inner) {
83	        if (!enableCaching) {
84	            return inner;
85	        }
86	
87	        final boolean isTimeOrdered = isTimeOrderedStore(inner);
88	        if (isTimeOrdered) {
89	            return new TimeOrderedCachingWindowStore(
90	                inner,
91	                storeSupplier.windowSize(),
92	                storeSupplier.segmentIntervalMs());
93	        }
94	
95	        return new CachingWindowStore(
96	            inner,
97	            storeSupplier.windowSize(),
98	            storeSupplier.segmentIntervalMs());
99	    }
